// RSS feed URLs — mirrors the app's .env RSS_FEEDS config
const feeds = [
  'https://techcrunch.com/category/artificial-intelligence/feed/',
  'https://feeds.arstechnica.com/arstechnica/technology-lab',
  'https://www.theverge.com/rss/ai-artificial-intelligence/index.xml'
];

return feeds.map(url => ({ json: { feedUrl: url } }));

const SOURCE_MAP = {
  'techcrunch.com': 'TechCrunch',
  'arstechnica.com': 'Ars Technica',
  'theverge.com': 'The Verge'
};

function extractSourceName(url) {
  for (const [domain, name] of Object.entries(SOURCE_MAP)) {
    if (url.includes(domain)) return name;
  }
  try { return new URL(url).hostname; } catch { return 'Unknown'; }
}

function stripHtml(text) {
  if (!text) return '';
  return text.replace(/<[^>]*>/g, ' ').replace(/&[^;]+;/g, ' ').replace(/\s+/g, ' ').trim();
}

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const url = (data.link || data.guid || '').trim();
  if (!url) continue;

  results.push({
    json: {
      title: (data.title || 'Untitled').trim(),
      url,
      source: extractSourceName(url),
      published_at: data.isoDate || data.pubDate || new Date().toISOString(),
      category: 'ai',
      summary: stripHtml(data.contentSnippet || data.summary || '').slice(0, 500) || null,
      content: stripHtml(data['content:encoded'] || data.content || '') || null
    }
  });
}

return results;

const articles = $input.all().map(i => i.json);
const lines = ['# AI News Digest', ''];

if (articles.length === 0) {
  lines.push('_No articles found._');
} else {
  for (const a of articles) {
    const date = a.published_at ? new Date(a.published_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '';
    lines.push(`### [${a.title}](${a.url})`);
    lines.push(`${date} · ${a.source}`);
    if (a.summary) lines.push(a.summary.slice(0, 200));
    lines.push('');
  }
}

return [{
  json: {
    ingested: articles.length,
    indexed: 0,
    digest: {
      articleCount: articles.length,
      markdown: lines.join('\n')
    }
  }
}];
